def min_prefix_suffix_max_length(words: List[str]) -> int:
    """
    Returns the maximum of the minimum length of any prefix and any suffix of the words.
    """
    max_length = 0
    for word in words:
        prefix_length = 0
        while word[prefix_length] == word[-prefix_length-1]:
            prefix_length += 1
        max_length = max(max_length, prefix_length)
    for i, word in enumerate(words):
        reverse_word = word[::-1]
        rev_prefix_length = 0
        while word[:rev_prefix_length] == reverse_word[rev_prefix_length:]:
            rev_prefix_length += 1
        max_length = max(max_length, min(rev_prefix_length, len(word) - rev_prefix_length))
    return max_length

