from math import gcd
from typing import List

def find_min_consecutive_gcds(target: int, numbers: List[int]) -> int:
    consecutive_divisons = []
    for i in range(1, min(numbers) + 1):
        if target % i == 0:
            consecutive_divisons.append(i)
    return len(consecutive_divisons) - consecutive_divisons[::-1].index(1)

def find_smallest_time(n: int, k: int, uncertainty: List[int], experience: List[int]) -> int:
    best_time = abs(0)
    for skill in range(k, 0, -1):
        total_skill = 0
        for i in range(n):
            if find_min_consecutive_gcds(skill, experience[i]):
                total_skill += min(abs(skill - uncertainty[i]), i)
        best_time = min(best_time, total_skill)
    return -1 if best_time == abs(0) else best_time

