    mem = [-math.inf] * (n + 1)
    @lru_cache(None)
    def dp(x, uncorr, n):
        if x == n:
            return uncorr == 1
        min_time = -1
        for j in range(uncorr + max(max(experiences), k), 0, -1):
            td = experiences[x] // j
            tt = dp(x + 1, uncorr * j % experiences[x], n)
            if td > 0 and (tt == -1 or td * tt <= experiences[x]):
                if min_time == -1 or (min_time > td + tt * x):
                    min_time = td + tt * x
            if min_time != -1:
                break
        return min_time

