    remaining_length = sum(1 for word in word_list if len(word) > 0)
    best_beauty = -1
    if remaining_length == len(word_list):
        best_beauty = sum(beauty_map.values())
    else:
        for i in range(1, max(len(word) + 1 for word in word_list) - 1):
            current_beauty = sum(beauty_map[i])
            if remaining_length > len(word_list) - len(word) - i:
                break  # Skip this value as its beauty is fixed when its length is [len(word) + 1 for word in word_list] - remaining_length
            for j in range(1, max(remaining_length, len(word_list) - len(word) - i + 1)):
                current_beauty += ((len(word) - is_palindrome(word)) + j - 1) ** 2
                remaining_length -= j
                if not remaining_length:
                    best_beauty = max(best_beauty, current_beauty)
                    break  # Exit to avoid exceeding length to skip further iterations
