        # Point1 is on the cone's side surface and point2 is on the base
        return round(math.sqrt(point1_z ** 2 + (h * math.sqrt(point1_z ** 2 + math.pow(point1_x - point2_x, 2) + math.pow(point1_y - point2_y, 2))) ** 2 + point1_z * (math.sqrt(point1_z ** 2 + math.pow(point1_x - point2_x, 2) + math.pow(point1_y - point2_y, 2)) * point1_x / point2_x)), 6)

    if point1_x < 0 and point2_x < 0 and abs(point1_y + math.sqrt(h*h + point1_x*point1_x)) < point2_y < abs(point1_y + 2 * math.sqrt(h*h + point1_x*point1_x)) and point1_x + r < point2_x - h < point1_x + 2 * r and abs(point1_z - point2_z) < 10**(-13):
        # Point1 is on the cone's side surface and point2 is on the other side of the base
        return round(math.sqrt(point1_z ** 2 + (h * math.sqrt(math.pow(point1_x - point2_x, 2) + point1_y ** 2 + r*r)) ** 2 + 2 * point1_z * xy_length), 6)

    if point1_x - r > 0 and point2_x - r > 0 and abs(point1_y - point2_y) < r and abs(point1_z + point2_z) < 10**(-13) and point1_x > h + point2_x and r*h*r + r*point1_x < point1_x*point2_x + 2*r*r:
        # Point1 is on the cone's side surface, point2 is on the horizontal line through the base
        return round(math.sqrt(point1_z ** 2 + (math.sqrt(point1_x + h) ** 2 + math.pow(point1_y - point2_y, 2)) ** 2 + 2 * point1_z * float(point1_x) / point2_x), 6)

def main():
    r, h = map(float, input().split())
    point1 = tuple(map(float, input().split()))
    point2 = tuple(map(float, input().split()))
    print(shortest_path(r, h, point1, point2))

if __name__ == "__main__":
    main()
