def longest_common_prefix(s1, s2):
    min_len = min(len(s1), len(s2))
    for i in range(min_len):
        if s1[i] == s2[i]:
            continue
        else:
            return s1[:i]
    return s1[:min_len]

def longest_common_suffix(s1, s2):
    min_len = min(len(s1), len(s2))
    for i in range(min_len, 0, -1):
        if s1[-i] == s2[-i]:
            continue
        else:
            return s2[-i:]
    return s2[-min_len:]

def beauty_of_stanza(words):
    p_prefix = ""  # longest prefixal rhyme
    s_suffix = ""  # longest suffixal rhyme
    for word in words:
        p_prefix = longest_common_prefix(p_prefix, word) if p_prefix else word
        s_suffix = longest_common_prefix(word, s_suffix) if s_suffix else word
    l_p = len(p_prefix)
    l_s = len(s_suffix)
    return min(l_p, l_s)**2

def main():
    input()
    n = int(input())
    words = [input() for _ in range(n)]
    max_beauty = 0
    for i in range(n):
        for j in range(n):
            if i != j:
                result = beauty_of_stanza(words[:i] + words[i+1:]) + beauty_of_stanza(words[:j] + words[j+1:])
                max_beauty = max(max_beauty, result)
    print(max_beauty)

if __name__ == "__main__":
    main()
