def switch_direction(ant):
    if ant == 'R':
        return 'L'
    elif ant == 'L':
        return 'R'
    else:
        return ant

def ants_positions(t, positions, directions, m):
    n = len(positions)
    for i in range(n):
        if directions[i] == 'L':
            positions[i] -= t // m
        else:
            positions[i] += t // m

        if positions[i] < 1 or positions[i] > m:
            positions[i] = switch_direction(directions[i])
            if directions[i] == 'R':
                positions[i] += 1
            else:
                positions[i] -= 1

    return positions

# Read input values
n, m, t = map(int, input().split())  
positions = list(map(int, input().split()))
directions = list(input().split())  

# Calculate and print the positions of the ants after t time units
print(" ".join(map(str, ants_positions(t, positions, directions, m))))
