from math import comb

def add_combinations(nums, queries):
    # Add elements from 1 to n based on queries
    for l, r, k in queries:
        for i in range(l-1, r):
            nums[i] = (nums[i] + comb(k, i) * k % 1000000007) % 1000000007
    return nums

def main():
    n, m = map(int, input().split())
    nums = list(map(int, input().split()))
    queries = []
    for _ in range(m):
        l, r, k = map(int, input().split())
        queries.append((l-1, r-1, k))

    added_nums = add_combinations(nums, queries)
    for num in added_nums:
        print(num, end=' ')
    print()

if __name__ == "__main__":
    main()
